function onMessageReceived(payload) {
    if (!payload || typeof payload !== "object")
        return

    if (payload.action === "set_prompt") {
        promptEditor.text = String(payload.text || "")
        return
    }

    if (payload.action === "inspect_selector") {
        var selector = String(payload.selector || "").trim()
        if (selector.length > 0) {
            webView.runJavaScript(
                "window.__spellPhxInspector && window.__spellPhxInspector.inspectSelector("
                    + JSON.stringify(selector) + ", \"scripted\")"
            )
        }
        return
    }

    if (payload.action === "trigger_send_to_agent") {
        sendSelectionToAgent()
        return
    }

    if (payload.action === "task_result") {
        if (payload.ok) {
            quickFixState = "success"
            quickFixResultText = String(payload.output || "Quick fix completed.")
            statusText = "Quick fix completed"
        } else {
            quickFixState = "error"
            quickFixResultText = "Quick fix failed: " + String(payload.error || "Unknown error")
            statusText = "Quick fix failed"
        }
        return
    }

    if (payload._rid && payload._rid === pendingLocationRid) {
        resolvingSelection = false
        if (payload.error) {
            resolutionErrorText = String(payload.error)
            statusText = "Tidewave source resolution failed"
        } else {
            var ownerLocation = String(payload.result || "").trim()
            if (ownerLocation.length > 0) {
                if (sourceLocationText.length > 0 && sourceLocationText.indexOf(ownerLocation) < 0)
                    sourceLocationText += "\nComponent owner: " + ownerLocation
                else if (sourceLocationText.length === 0)
                    sourceLocationText = ownerLocation
            }

            if (pendingReadRid.length === 0) {
                var location = effectiveLocation()
                if (location)
                    requestSourceExcerpt(location.path, location.line)
            }

            statusText = "Resolved source location via Tidewave"
        }
        return
    }

    if (payload._rid && payload._rid === pendingDocsRid) {
        if (payload.error) {
            docsText = "Docs lookup failed: " + String(payload.error)
        } else {
            docsText = String(payload.result || "")
        }
        return
    }

    if (payload._rid && payload._rid === pendingReadRid) {
        pendingReadRid = ""
        if (payload.error) {
            sourceExcerptText = "Source excerpt read failed: " + String(payload.error)
        } else {
            sourceExcerptText = String(payload.result || "")
            statusText = "Loaded source excerpt around the selected DOM owner"
        }

